{{ config(materialized='table') }}

with
dim_customer_source as (
    select
        customer_business_key,
        customer_external_id,
        customer_name,
        customer_email_domain,
        customer_city,
        customer_country,
        line_order_date
    from {{ ref("ecommerce__order_star__base") }}
),
dim_customer_ranked as (
    select
        customer_business_key,
        customer_external_id,
        customer_name,
        customer_email_domain,
        customer_city,
        customer_country,
        row_number() over (partition by customer_business_key order by line_order_date desc) as dpf_version_rank
    from dim_customer_source
),
dim_customer_current as (
    select
        customer_business_key,
        customer_external_id,
        customer_name,
        customer_email_domain,
        customer_city,
        customer_country
    from dim_customer_ranked
    where dpf_version_rank = 1
)

select
    cast(customer_business_key as {{ dpf_type('string') }}) as customer_business_key,
    cast(customer_external_id as {{ dpf_type('string') }}) as customer_external_id,
    cast(customer_name as {{ dpf_type('string') }}) as customer_name,
    cast(customer_email_domain as {{ dpf_type('string') }}) as customer_email_domain,
    cast(customer_city as {{ dpf_type('string') }}) as customer_city,
    cast(customer_country as {{ dpf_type('string') }}) as customer_country
from dim_customer_current
